insert into public.news_stories
  (slug, legacy_id, story_date, sort_order, title, source, url, summary, implications, tags, pinned, status)
values
  ('2026-08-25-the-great-flattening-is-shrinking-management-without', '2026-08-25-0', '2026-08-25'::date, 0, 'The "Great Flattening" Is Shrinking Management Without Preparing Those Who Remain', 'HR Executive', 'https://hrexecutive.com/great-flattening-is-shrinking-management-without-preparing-those-who-remain/', 'Only 6% of leaders say their middle managers are prepared to lead through change across most of the organization; roughly 19% say managers are unprepared company-wide and another 19% simply don''t know. Two-thirds of organizations provide manager development resources and half offer coaching, yet just 10% systematically use span-of-control data to track how management roles are actually changing.', 'Organizational leaders flattening structures are removing a layer whose replacement capability they cannot measure — span-of-control instrumentation is the missing diagnostic before further delayering.', ARRAY['leadership and culture', 'workforce transformation']::text[], true, 'published'),
  ('2026-08-24-women-hold-roughly-1-in-4-new-ai-roles-and-13-of-ai-company', '2026-08-24-0', '2026-08-24'::date, 0, 'Women Hold Roughly 1 in 4 New AI Roles — and 13% of AI-Company Executive Seats', 'HR Dive', 'https://www.hrdive.com/news/women-are-significantly-underrepresented-in-the-ai-workforce/828485/', 'Women''s share of AI roles sits about 10 percentage points below their share of non-AI roles — 26% of new AI hires in 2025 versus roughly half of non-AI hires. The gap widens with seniority: 20% of Head of AI roles, 26% of Director of AI, and 13% of executive leadership at AI companies. A typical LinkedIn AI posting advertises ~$177k against ~$80k for non-AI roles.', 'Capability builders running AI upskilling should treat participation equity as a design constraint, not a reporting metric — the compounding wage premium means today''s access gap becomes tomorrow''s leadership pipeline gap.', ARRAY['skills development', 'macro signals', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-08-24-skilled-trades-demand-nearly-doubles-in-three-years-as-ai', '2026-08-24-1', '2026-08-24'::date, 1, 'Skilled Trades Demand Nearly Doubles in Three Years as AI Infrastructure Pulls Labour Away', 'HR Dive', 'https://www.hrdive.com/news/skilled-labor-demand-is-exploding-ai-is-both-a-cause-and-a-solution-nfpa/828486/', 'Demand for skilled labour has roughly doubled over three years, with about a third of NFPA respondents attributing the rise to data-centre and AI-infrastructure buildout drawing electricians, HVAC and technical trades away from other sectors. Hiring an electrician now takes longer than hiring a software developer, and a retirement cliff in the engineering and technical workforce compounds it as vocational pipelines fail to keep pace.', 'Organisational leaders planning physical-asset or facilities work should model trade-labour scarcity as a schedule risk on par with capital cost, and build direct pipeline relationships rather than relying on spot hiring.', ARRAY['macro signals', 'skills development', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-24-what-gets-your-best-employees-to-stay-mobility-barriers-not', '2026-08-24-2', '2026-08-24'::date, 2, '"What Gets Your Best Employees to Stay" — Mobility Barriers, Not Engagement Scores, Explain Retention', 'MIT Sloan Management Review', 'https://sloanreview.mit.edu/article/what-gets-your-best-employees-to-stay/', 'The authors argue retention of high performers is better explained by understanding what actually constrains or enables their mobility than by generic engagement interventions. The framing shifts retention from a satisfaction problem to a structural one about outside options and switching costs.', 'Leaders should audit why their strongest people could leave — and what internal moves genuinely compete with the external market — rather than reinvesting in engagement surveys that don''t discriminate between stayers and leavers.', ARRAY['leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-08-24-the-power-of-opportunity-mindset-in-hiring-merit-based', '2026-08-24-3', '2026-08-24'::date, 3, '"The Power of Opportunity Mindset in Hiring" — Merit-Based Hiring Lacks the Rigour It Claims', 'MIT Sloan Management Review', 'https://sloanreview.mit.edu/article/the-power-of-opportunity-mindset-in-hiring/', 'Castilla reconsiders merit-based hiring, arguing that many nominally meritocratic selection processes lack the evidentiary rigour to actually identify capability, and proposes an opportunity-oriented alternative to reduce reliance on unvalidated proxies.', 'Anyone standing up skills-based hiring should validate that their assessments predict performance — otherwise "skills-first" reproduces the same proxy-based judgment it was meant to replace.', ARRAY['leadership and culture', 'skills development']::text[], false, 'published'),
  ('2026-08-21-is-your-organizational-culture-too-nice', '2026-08-21-0', '2026-08-21'::date, 0, 'Is Your Organizational Culture Too Nice?', 'Harvard Business Review', 'https://hbr.org/2026/08/is-your-organizational-culture-too-nice', 'Argues that organizations optimizing for harmony and comfort over candor systematically undermine performance. The authors call for leaders to model direct feedback, redesign review and governance routines to reward substantive debate over polite approval, and demonstrate that tougher calls produce better outcomes.', 'A structural diagnosis for leaders whose transformation or performance initiatives stall despite apparent alignment — the failure mode is often manufactured consensus, not lack of strategy.', ARRAY['leadership and culture']::text[], false, 'published'),
  ('2026-08-21-cedefop-updates-skills-forecast-new-data-to-guide-europes', '2026-08-21-1', '2026-08-21'::date, 1, 'Cedefop Updates Skills Forecast: New Data to Guide Europe''s Skills and Labour Market Policy to 2035', 'Cedefop', 'https://www.cedefop.europa.eu/en/news/cedefop-updates-skills-forecast-new-data-guide-europes-skills-and-labour-market-policy-2035', 'EU employment is projected to grow 4%+ through 2035, but with sharp sectoral divergence: ICT (+2.5%/yr, Romania +7.8%) and healthcare surging on green transition and demographic aging, while coal (-10.7%/yr) and manufacturing fuels (-4.4%/yr) decline steeply. A rapidly aging workforce (65+ growing 7%+/yr) intensifies replacement-demand pressure on high-skilled roles.', 'A concrete, non-US data point for workforce planners benchmarking skills investment against demographic and green-transition timelines rather than AI alone.', ARRAY['macro signals', 'skills development']::text[], false, 'published'),
  ('2026-08-20-goldman-sachs-ais-hiring-drag-is-now-visible-in-the-data-and', '2026-08-20-0', '2026-08-20'::date, 0, 'Goldman Sachs: AI''s Hiring Drag Is Now Visible in the Data — and Hits Entry-Level Workers Hardest', 'CNBC', 'https://www.cnbc.com/2026/08/19/goldman-ai-impact-employment-jobs.html', 'Goldman Sachs'' cross-country analysis finds AI exposure carries roughly 3x the employment drag for entry-level workers versus the broader labor market, with call-center roles down as much as 39% below trend in the US. The effect is concentrated in a narrow band of industries — IT services, publishing, computer programming — and shows up mainly as suppressed hiring rather than layoffs, consistent across the US, Germany, Australia and Canada.', 'Organizational leaders should treat entry-level pipeline erosion as a structural planning problem, not a cyclical blip, since the mechanism (reduced hiring, not firing) won''t show up in layoff headlines.', ARRAY['macro signals', 'research and insights', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-19-fear-of-skills-obsolescence-hits-58-of-us-workers-with', '2026-08-19-0', '2026-08-19'::date, 0, 'Fear of Skills Obsolescence Hits 58% of US Workers, With Sharpest Spikes in Tech and Finance', 'HR Dive', 'https://www.hrdive.com/news/workers-report-fobo-a-fear-of-becoming-obsolete/828115/', 'A new Harris Poll/ETS survey of 15,357 US adults finds 58% of workers fear becoming professionally obsolete due to skills gaps — rising to 74% among tech workers and 73% in financial services. Two-thirds say upskilling costs are hard to cover and 63% struggle to find time to learn, yet nearly 9 in 10 want employers to push credential-setting.', 'The "FOBO" framing gives capability builders a concrete anxiety metric to design reskilling programs around — cost and time barriers, not motivation, are the binding constraint.', ARRAY['skills development', 'research and insights']::text[], false, 'published'),
  ('2026-08-19-india-and-japan-advance-roadmap-for-structured-skilled', '2026-08-19-1', '2026-08-19'::date, 1, 'India and Japan Advance Roadmap for Structured Skilled-Worker Mobility', 'The Hans India', 'https://www.thehansindia.com/amp/business/india-japan-discuss-roadmap-to-expand-skilled-workforce-mobility-1109638', 'India and Japan convened government, industry and training-provider stakeholders to build structured pathways combining technical training, Japanese-language instruction, and cultural preparation for Indian workers, part of a five-year target to exchange 500,000 personnel. Japanese employers will subsidize vocational and language training in India.', 'A concrete model of demographic-driven bilateral labor mobility (aging Japan, youth-abundant India) that other skills-scarce economies are likely to replicate — worth tracking as a template for skills-first immigration design.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-19-leadership-confidence-far-outpaces-readiness-for-ai-driven', '2026-08-19-2', '2026-08-19'::date, 2, 'Leadership Confidence Far Outpaces Readiness for AI-Driven Change', 'HR Executive', 'https://hrexecutive.com/new-research-reveals-leadership-readiness-gap-amid-rapid-workplace-change/', 'While 98% of people managers believe they''re equipped to lead through future challenges, only 35% say AI has meaningfully simplified their role, and there''s a sharp confidence gap by level: 66% of C-suite leaders feel ready for what''s ahead versus just 42% of middle managers. Mid-level managers also receive far less training for difficult conversations (38%) than executives (61%).', 'The gap sits specifically at the frontline-manager layer — the group actually translating AI-driven change into daily team behavior — making manager capability-building a higher-leverage investment than executive AI briefings.', ARRAY['leadership and culture', 'workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-08-18-your-future-workforce-already-works-for-you', '2026-08-18-0', '2026-08-18'::date, 0, 'Your Future Workforce Already Works for You', 'Fortune', 'https://fortune.com/2026/08/07/your-future-workforce-already-works-for-you-mercer-ravin-jesuthasan/', 'Mercer''s Ravin Jesuthasan argues organizations should manage talent as a portfolio of skills deployed flexibly alongside AI rather than as static roles, with reskilling and deliberate on-the-job learning as the primary lever for durable advantage.', 'Reinforces the skills-based-organization case for leaders weighing whether to redesign job architecture around skills rather than titles.', ARRAY['skills development', 'workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-08-14-ai-employment-gap-for-young-workers-widens-to-19', '2026-08-14-0', '2026-08-14'::date, 0, 'AI Employment Gap for Young Workers Widens to 19%', 'Stanford Digital Economy Lab', 'https://digitaleconomy.stanford.edu/news/canariesaug26/', 'New ADP payroll analysis (Nov 2022–Jun 2026) finds employment for 22–25-year-olds in highly AI-exposed occupations now runs ~19% below where it would be had it tracked less-exposed peers — up from 15% a year ago. The adjustment is happening through reduced entry-level hiring, not layoffs, and the researchers stress there''s no evidence of broad, economy-wide displacement.', 'Capability builders and hiring managers should treat entry-level pipelines in codified-knowledge occupations as the leading edge of AI''s labor effect — the risk shows up as a hiring freeze on juniors, not a layoff wave.', ARRAY['skills development', 'macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-08-14-buried-in-openais-own-research-no-correlation-between-ai-use', '2026-08-14-1', '2026-08-14'::date, 1, 'Buried in OpenAI''s Own Research: No Correlation Between AI Use and Revenue per Employee', 'Fortune', 'https://fortune.com/2026/08/13/buried-in-openais-latest-research-no-correlation-between-ai-use-and-revenue-per-employee/', 'A 69-page OpenAI-co-authored study (with Columbia Business School and Wharton researchers) analyzing enterprise ChatGPT usage from Oct 2025–Mar 2026 finds token usage per employee is not meaningfully associated with revenue per employee once controls are applied. Senior leaders use AI least intensively even as they drive adoption decisions; early-career employees use it most.', 'Leaders relying on adoption/usage metrics as a proxy for AI ROI are measuring the wrong thing; the paper suggests real value capture depends on empowering frontline usage rather than top-down mandates.', ARRAY['workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-08-13-oracle-prepares-new-round-of-ai-linked-layoffs-ahead-of', '2026-08-13-0', '2026-08-13'::date, 0, 'Oracle Prepares New Round of AI-Linked Layoffs Ahead of Fiscal Q2', 'Business Insider', 'https://finance.yahoo.com/technology/ai/articles/oracle-planning-round-layoffs-august-134527039.html', 'Oracle has drawn up plans for a new round of job cuts, with managers asked to submit affected-employee lists ahead of its fiscal Q2 opening September 1. This follows a 13% (21,000-person) headcount decline over the prior fiscal year, which the company partly attributes to AI adoption and deployment as it borrows heavily to fund AI data-center buildout.', 'A concrete case study in how AI capex is being funded partly through workforce reduction rather than reinvestment — a pattern worth tracking as a leading indicator for other capital-intensive tech firms.', ARRAY['workforce transformation', 'macro signals']::text[], false, 'published'),
  ('2026-08-13-tech-and-finance-sector-job-losses-tied-to-ai-persist-at-28', '2026-08-13-1', '2026-08-13'::date, 1, 'Tech and Finance Sector Job Losses Tied to AI Persist at ~28,000/Month', 'Bloomberg', 'https://www.bloomberg.com/news/articles/2026-07-01/tech-and-finance-sectors-losing-28-000-jobs-monthly-show-ai-impact-on-labor', 'Payroll declines in financial-activities and information sectors — where AI adoption has been fastest — have accelerated through 2026, averaging 28,000 job losses per month based on government data. Bloomberg''s August 7 segment tied this directly to July''s unexpected national payroll contraction.', 'Sector-specific AI displacement is now visible in monthly government labor data, not just anecdote — a signal that organizational leaders should start distinguishing AI-driven restructuring from cyclical hiring softness in workforce planning.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-10-kyndryls-2026-people-readiness-report-workforce-ai-readiness', '2026-08-10-0', '2026-08-10'::date, 0, 'Kyndryl''s 2026 People Readiness Report: Workforce AI-Readiness Fell Even as Adoption Surged', 'Kyndryl', 'https://www.kyndryl.com/us/en/insights/people-readiness-report-2026', 'In a global study of 1,100 senior business and technology leaders across eight countries, only 23% say their workforce is ready for AI — down 6 points from 2025 — even as AI deployment climbed to 57% of enterprises. Leaders rate IT infrastructure readiness far higher (35%) than workforce readiness, governance/compliance, and culture (23–25%), and only 11% of enterprises say they''re hitting their AI goals.', 'The bottleneck on AI ROI is shifting from technical deployment to human and governance readiness — capability builders should prioritize readiness diagnostics over further tool rollout.', ARRAY['workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-08-08-world-bank-ai-offers-a-growth-lifeline-to-developing', '2026-08-08-0', '2026-08-08'::date, 0, 'World Bank: AI Offers a Growth "Lifeline" to Developing Economies — But Only With the Right Investments', 'World Bank Group', 'https://www.worldbank.org/en/news/press-release/2026/08/04/ai-offers-lifeline-to-developing-economies-in-an-era-of-weak-growth', 'New flagship report finds only 4.5% of jobs in developing economies face automation risk, versus 14.2% in wealthy nations, while nearly 16% of jobs in emerging markets could see meaningful productivity gains from AI — arriving as developing economies post their weakest average growth in thirty years. The Bank frames AI as a conditional opportunity: gains depend on foundational investment in electricity, connectivity, data infrastructure, and workforce skills, or the technology risks deepening global inequality instead.', 'Emerging-market leaders and capability builders have a narrow window to pair AI adoption with infrastructure and skills investment before the productivity gap with wealthy nations hardens into a structural divide.', ARRAY['macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-08-08-eu-begins-enforcing-ai-transparency-rules-while-deferring', '2026-08-08-1', '2026-08-08'::date, 1, 'EU Begins Enforcing AI Transparency Rules, While Deferring Harder Employment-AI Obligations to 2027', 'European Commission', 'https://commission.europa.eu/news-and-media/news/safer-and-more-transparent-ai-2026-08-02_en', 'As of August 2, 2026, the EU began enforcing Article 50 transparency rules requiring disclosure when people interact with AI systems, AI-generated content, or emotion-recognition/biometric tools, with fines up to €15 million or 3% of global turnover. Separately, the Digital Omnibus (signed July 8, 2026) pushed full high-risk compliance for employment-related AI — recruitment, performance monitoring, termination decisions — from August 2026 to December 2027.', 'HR and legal teams face live transparency obligations for AI-enabled HR tools now, even though the harder compliance deadline for high-risk employment AI has been pushed out — a two-stage governance timeline worth planning for immediately rather than in 2027.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-08-shrms-midyear-check-on-2026-hr-predictions-upskilling-and-ai', '2026-08-08-2', '2026-08-08'::date, 2, 'SHRM''s Midyear Check on 2026 HR Predictions: Upskilling and AI Recruiting Trends Tested Against Reality', 'SHRM', 'https://www.shrm.org/topics-tools/tracking-shrms-2026-workplace-predictions-midyear-review', 'SHRM''s midyear review tracks how its seven predicted 2026 HR trends — including AI-driven recruiting, real-time upskilling, and shifting inclusion & diversity strategy — are actually playing out. Related SHRM data shows employer AI-tool subscriptions climbing to 33% of organizations (up 17 points from 2025), with skills-based, data-driven talent strategy continuing to outpace credential-based hiring.', 'Capability builders should use this as a checkpoint to compare their own upskilling and AI-adoption pace against the trend curve HR leaders predicted in January, correcting course before year-end planning locks in.', ARRAY['skills development', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-08-new-frontline-data-role-clarity-is-high-but-managers-are', '2026-08-08-3', '2026-08-08'::date, 3, 'New Frontline Data: Role Clarity Is High, But Managers Are Being Set Up to Fail', 'Forbes Business Council', 'https://www.forbes.com/councils/forbesbusinesscouncil/2026/08/03/frontline-execution-at-the-last-mile-closing-the-enablement-gap-between-leaders-and-workers/', 'A survey of 1,594 frontline workers and managers in retail, grocery, and hospitality finds workers rate role clarity highly (4.68/5), yet 46–52% of managers report new initiatives launch without adequate support, and only 23% of frontline workers believe senior leaders understand day-to-day workplace reality. Manager span of control widened from 10.9 to 12.1 direct reports over the past year, compounding the strain.', 'For organizations with large frontline workforces, the bottleneck to transformation is under-resourced middle management, not worker skill or clarity — a structural fix, not a training fix.', ARRAY['leadership and culture', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-06-googles-ai-and-economy-atlas-finds-workplace-ai-use-is', '2026-08-06-0', '2026-08-06'::date, 0, 'Google''s AI & Economy ATLAS Finds Workplace AI Use Is Augmentation, Not Automation', 'Google', 'https://blog.google/innovation-and-ai/technology/research/understanding-the-ai-economy/', 'Google''s inaugural AI & Economy ATLAS report analyzed 15 million de-identified Gemini interactions across 150 countries, 800 occupations, and 4,000 tasks. It found AI touches 68% of occupations (~90% of US employment) but workers use it for only ~21% of core tasks on average, with just 3% of occupations hitting heavy-use thresholds and 29% showing no meaningful use at all.', 'Provides the strongest empirical counterweight yet to displacement narratives — leaders planning workforce strategy around imminent automation of whole roles should recalibrate toward augmentation-focused reskilling.', ARRAY['research and insights', 'macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-06-ford-ibm-and-commonwealth-bank-of-australia-reverse-ai', '2026-08-06-1', '2026-08-06'::date, 1, 'Ford, IBM, and Commonwealth Bank of Australia Reverse AI-Driven Layoffs', 'CNBC', 'https://www.cnbc.com/2026/07/01/employers-who-laid-off-workers-for-ai-are-reversing-their-decisions.html', 'Ford is rehiring engineers after automated systems couldn''t handle quality issues, CBA reversed customer-service cuts after an AI voice bot increased call volume, and IBM is tripling entry-level hiring after AI handled only 94% of routine HR requests. Industry data shows 32% of US hiring managers who cut a role for AI later rehired for it, and 55% of leaders who made AI-related redundancies now call those calls wrong.', 'A concrete, named-company data point for the pilot-to-production failure pattern — leaders should treat AI-justified headcount cuts as reversible bets, not settled strategy, until task-level reliability is proven.', ARRAY['workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-08-06-the-elusiveness-of-merit-based-hiring', '2026-08-06-2', '2026-08-06'::date, 2, 'The Elusiveness of Merit-Based Hiring', 'MIT Sloan Management Review', 'https://sloanreview.mit.edu/article/the-elusiveness-of-merit-based-hiring/', 'Kyle Brink argues the common framing of DEI-versus-merit is a false dichotomy: true merit requires empirically validated selection practices, not the "face validity" most organizations rely on. He introduces the concept of a "merit mirage" — managers championing seemingly objective hiring criteria that have no demonstrated predictive power for job performance.', 'Organizational leaders retreating from DEI programs under political pressure should be warned that most of what they''re replacing it with ("merit") isn''t rigorously validated either — a credibility risk for skills-based hiring claims broadly.', ARRAY['research and insights', 'leadership and culture', 'skills development']::text[], false, 'published'),
  ('2026-08-06-three-ways-leading-manufacturers-are-preparing-their', '2026-08-06-3', '2026-08-06'::date, 3, 'Three Ways Leading Manufacturers Are Preparing Their Workforce for AI', 'World Economic Forum', 'https://www.weforum.org/stories/manufacturing-and-value-chains/ai-manufacturing-workplace-transformation/', 'Drawing on WEF''s Global Lighthouse Network manufacturing sites, the piece profiles how leading factories are operationalizing the Forum''s new Human-Machine Collaboration Framework (launched June 2026), which maps 80+ manufacturing and supply-chain jobs to show how tasks and skills evolve as autonomous systems spread. WEF estimates three in four industrial jobs will change substantially within a decade, requiring workers skilled in judgment, machine oversight, and governance rather than manual execution.', 'Capability builders in industrial and operational roles should prioritize training in oversight/governance skills now, ahead of the task-level disruption the framework projects.', ARRAY['workforce transformation']::text[], false, 'published'),
  ('2026-08-06-asia-pacific-leads-the-world-in-ai-adoption-and-faces-its', '2026-08-06-4', '2026-08-06'::date, 4, 'Asia Pacific Leads the World in AI Adoption — and Faces Its Steepest Talent Gap', 'JLL', 'https://www.jll.com/en-hk/newsroom/asia-pacific-leads-the-world-in-ai-adoption-across-real-estate-functions', 'APAC leads globally in AI deployment (52% in technology management, 51% in portfolio optimization) even as 61% of leaders expect workforce growth. Yet 42% cite an AI skills gap as their primary constraint — the highest of any region — and only 15% have reached full AI optimization maturity.', 'For organizational leaders in the region, adoption speed is outpacing capability-building; the gap between deployment and workforce readiness is now the binding constraint, not technology access.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-08-04-managers-say-they-dont-feel-ready-to-lead-an-ai-fluent', '2026-08-04-0', '2026-08-04'::date, 0, 'Managers Say They Don''t Feel Ready to Lead an AI-Fluent Workforce', 'HR Dive', 'https://www.hrdive.com/news/managers-say-they-dont-feel-ready-to-lead-an-ai-fluent-workforce/826354/', 'An Indeed/YouGov survey finds 43% of managers feel poorly or not-at-all equipped to lead AI-fluent employees, while 52% of workers say they aren''t getting the AI training they need. Employer expectations for AI use are running two-to-three times ahead of worker comfort levels, and 31% of employers expect AI fluency to be required for nearly every job within two years.', 'Organizations are outrunning their own change-management capacity — manager enablement, not just employee training, is becoming the binding constraint on AI adoption.', ARRAY['skills development', 'leadership and culture']::text[], false, 'published'),
  ('2026-08-04-managers-are-using-ai-to-make-layoff-and-firing-decisions', '2026-08-04-1', '2026-08-04'::date, 1, 'Managers Are Using AI to Make Layoff and Firing Decisions — With Little Oversight', 'HR Dive', 'https://www.hrdive.com/news/managers-are-using-ai-to-make-layoff-decisions/826697/', '59% of surveyed managers report using AI to help decide who gets laid off, and 58% for firing decisions — most commonly weighing performance, attendance, and cost. Concerningly, 14% say their AI tools factor in age (a protected class), 38% have received no ethical-AI training, and 58% can''t confirm their company tested the tools for bias.', 'AI governance in HR decision-making is running well ahead of policy, training, and bias auditing — a clear legal and reputational exposure for organizational leaders.', ARRAY['workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-08-04-bipartisan-federal-jobs-for-stars-act-would-cut-degree', '2026-08-04-2', '2026-08-04'::date, 2, 'Bipartisan "Federal Jobs for STARs Act" Would Cut Degree Requirements Across Federal Hiring', 'MeriTalk', 'https://www.meritalk.com/articles/bipartisan-bill-would-expand-skills-based-hiring-for-federal-jobs/', 'Reps. Bynum (D-OR), Krishnamoorthi (D-IL), Mackenzie (R-PA), and McGuire (R-VA) introduced legislation directing federal agencies to de-emphasize bachelor''s degree requirements where not essential, establish OPM-recognized skills-based qualifications for military/apprenticeship/technical-education backgrounds, and create a dedicated USAJobs portal for non-degree candidates.', 'Skills-based hiring is moving from private-sector practice into codified federal policy, which could set a benchmark (and talent pool precedent) other public and private employers reference.', ARRAY['skills development', 'research and insights']::text[], false, 'published'),
  ('2026-08-04-singapore-employers-pay-a-premium-for-ai-literacy-and', '2026-08-04-3', '2026-08-04'::date, 3, 'Singapore Employers Pay a Premium for AI Literacy and Critical Thinking Despite Cooling Hiring', 'ManpowerGroup Singapore', 'https://www.manpower.com.sg/en/insights/blogs/2026/06/manpowergroup-employment-outlook-survey-q3-2026', 'Singapore''s Net Employment Outlook fell to +13% for Q3 2026 — its lowest since Q4 2021 — yet 66% of employers say they''ll pay more for AI literacy and for critical thinking/problem-solving, and 64% for leadership and social influence. Hiring is becoming more selective, with investment concentrated on high-impact skills rather than headcount growth.', 'A slowing APAC hiring market is coexisting with rising skills premiums — a signal that "quality over quantity" hiring, not retrenchment from skills investment, is the emerging pattern leaders should plan around.', ARRAY['macro signals', 'skills development']::text[], false, 'published'),
  ('2026-07-30-half-of-europes-job-postings-are-shrinking-even-as-ai-roles', '2026-07-30-0', '2026-07-30'::date, 0, 'Half of Europe''s Job Postings Are Shrinking Even as AI Roles Surge', 'Indeed Hiring Lab', 'https://www.hiringlab.org/uk/blog/2026/07/27/july-2026-european-labour-market-chartbook/', 'Indeed''s Job Postings Index for the Euro Area stood at 105 as of July 17 — nearly 10% below where it started the year — with broad-based softening across countries, even as AI-related postings continue to grow on a separate, upward trajectory. Spain is a notable outlier, with a national index of 145 versus the euro-area average.', 'European employers are bifurcating hiring — cooling broadly while still competing hard for AI-adjacent talent — a signal for org leaders to reassess where headcount investment is actually flowing.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-30-job-hugging-is-cracking-engagement-data-shows-half-of', '2026-07-30-1', '2026-07-30'::date, 1, '"Job Hugging" Is Cracking: Engagement Data Shows Half of Stayers Don''t Want to Be There', 'Inc.', 'https://www.inc.com/bruce-crumley/the-job-hugging-trend-is-cracking-why-half-of-employees-are-now-looking-to-leave/91373100', 'While 77% of workers say they intend to stay with their current employer, only 18% say it''s because they genuinely want to — 56% cite financial pressure and job-market uncertainty. Researchers describe a "quiet cracking" pattern: employees mentally checking out while remaining in place, which correlates with lower engagement and productivity risk.', 'Retention metrics that look healthy (low turnover) may be masking a disengagement problem — leaders should pair stay-rate data with engagement/intent-to-stay-vs-want-to-stay splits.', ARRAY['macro signals']::text[], false, 'published'),
  ('2026-07-27-ai-adoption-is-outpacing-leadership-readiness-manpowergroup', '2026-07-27-0', '2026-07-27'::date, 0, 'AI Adoption Is Outpacing Leadership Readiness, ManpowerGroup Research Finds', 'ManpowerGroup Talent Solutions', 'https://www.mpgtalentsolutions.com/the-new-talent-equation', 'Only 3% of organizations say their leaders are highly prepared to manage AI-enabled ways of working, even as 78% report employee anxiety about job displacement. The strongest productivity gains come from human-AI collaboration (34%) rather than full automation (8%), suggesting the bottleneck has shifted from technology deployment to leadership capability and trust.', 'For organizational leaders, the AI transformation ceiling is now a people-capability ceiling, not a technology one — leadership development budgets are likely underweighted relative to AI tooling spend.', ARRAY['leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-27-nearly-half-of-u-s-workers-are-staying-put-out-of-fear-not', '2026-07-27-1', '2026-07-27'::date, 1, 'Nearly Half of U.S. Workers Are Staying Put Out of Fear, Not Loyalty — and AI Anxiety Is Driving a Disengagement Spiral', 'Founder Reports', 'https://founderreports.com/employee-engagement-report/', '47% of workers cite job-market or employment-prospect fears as a reason for staying, versus 45% staying by genuine choice. Fear-driven "stayers" default to minimal effort (only 30% go beyond assigned tasks) versus voluntary stayers (49% discretionary effort), and workers who fear automation are twice as likely to believe extra effort is futile.', 'Retention metrics alone are masking a quality-of-engagement problem — leaders should treat "why they''re staying" as a leading indicator distinct from headline retention rates.', ARRAY['macro signals']::text[], false, 'published'),
  ('2026-07-27-ai-automation-is-freezing-entry-level-hiring-building-long', '2026-07-27-2', '2026-07-27'::date, 2, 'AI Automation Is Freezing Entry-Level Hiring, Building Long-Term "Capability Debt"', 'Gartner; McKinsey & Company', 'https://www.gartner.com/en/newsroom/press-releases/2026-7-27-gartner-survey-finds-ai-automation-is-reducing-some-entry-level-hiring-at-nearly-one-quarter-of-organizations', 'A new Gartner survey of 110 HR heads finds 22% of CHROs report business leaders have stopped hiring for entry-level positions due to automated task execution, even though only 20% of the 95% of organizations that deployed AI tools in the past year report significant or transformational value. McKinsey frames the same trend as mounting "capability debt": a 2025 survey found 51% of organizations say generative AI is reducing their need for entry-level roles, widening the gap between the leadership judgment companies will need and the shrinking early-career pipeline meant to build it.', 'Capability builders must urgently redesign early-career roles around higher-value judgment work rather than routine execution — cutting entry-level pipelines for short-term efficiency gains risks a long-term leadership void.', ARRAY['workforce transformation', 'skills development', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-27-the-rise-of-the-agent-manager-and-the-re-engineering-of', '2026-07-27-3', '2026-07-27'::date, 3, 'The Rise of the "Agent Manager" and the Re-Engineering of Middle Management', 'McKinsey & Company', 'https://www.mckinsey.com/capabilities/people-and-organizational-performance/our-insights', 'McKinsey''s latest organizational analysis tracks a fundamental transformation in middle management as autonomous virtual agents absorb daily administrative tracking and task assignment. Successful enterprises are shifting management profiles from supervisory coordinators to "Agent Managers" — leaders who orchestrate hybrid human-agent teams, curate creative output, and enforce ethical guardrails.', 'Organizational leaders must redesign middle-management career tracks away from administrative supervision toward human-agent orchestration, ethical auditing, and capability building.', ARRAY['leadership and culture', 'workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-07-27-hrs-dual-mandate-and-the-1-to-5-investment-rule', '2026-07-27-4', '2026-07-27'::date, 4, 'HR''s Dual Mandate and the $1-to-$5 Investment Rule', 'McKinsey & Company', 'https://www.mckinsey.com/capabilities/people-and-organizational-performance/our-insights/the-organization-blog/hrs-dual-mandate-in-the-ai-era', 'McKinsey finds that while 88% of corporations deploy automated systems in at least one business function, only 39% report material EBIT contributions. The research establishes a strict capital allocation benchmark: for every $1 spent on technology infrastructure, organizations must invest $5 in process redesign, capability building, and human-system integration.', 'Enterprise transformation leads must treat workflow simplification and human-capability development as primary capital expenditures rather than secondary administrative costs.', ARRAY['workforce transformation', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-27-oecd-employment-outlook-2026-geographic-disparities-widen-as', '2026-07-27-5', '2026-07-27'::date, 5, 'OECD Employment Outlook 2026: Geographic Disparities Widen as AI and Trade Reshape Local Labor Markets', 'OECD', 'https://www.oecd.org/en/publications/oecd-employment-outlook-2026_7e710f54-en.html', 'The OECD''s flagship annual report finds employment-rate gaps exceeding 20 percentage points between small regions within the same member country, with AI and trade shocks reshaping local labor markets unevenly — some regions lose manufacturing jobs while others gain service-sector work. Real wage growth across OECD economies slowed to 2.2% in Q1 2026, down from 2.7% a year earlier.', 'Organizational leaders operating across multiple regions should expect divergent local talent availability and wage pressure rather than a uniform national picture.', ARRAY['macro signals', 'research and insights', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-27-upworks-future-workforce-index-2026-share-of-independent', '2026-07-27-6', '2026-07-27'::date, 6, 'Upwork''s Future Workforce Index 2026: Share of Independent Professionals Jumps as AI Raises the Premium on Judgment', 'Upwork', 'https://www.globenewswire.com/news-release/2026/07/14/3326964/0/en/Upwork-s-Future-Workforce-Index-2026-How-AI-is-Redefining-the-Value-of-Work-as-Skilled-Freelancing-Accelerates.html', 'Upwork''s second annual index, surveying 2,400 U.S.-based skilled knowledge workers, found the share identifying as independent professionals jumped from 28% to 38% in one year. The report frames this as AI commoditizing routine execution while raising the market value of judgment-driven, expertise-based work.', 'Organizational leaders may need to compete harder to retain top judgment-heavy talent as AI lowers the cost of going independent for skilled professionals; note the source has a commercial interest in this narrative.', ARRAY['workforce transformation', 'macro signals']::text[], false, 'published'),
  ('2026-07-24-oecd-skills-in-the-ai-age-ai-papers-no-60', '2026-07-24-0', '2026-07-24'::date, 0, 'OECD: "Skills in the AI Age" (AI Papers No. 60)', 'OECD', 'https://www.oecd.org/en/publications/skills-in-the-ai-age_972bd15e-en.html', 'New OECD analysis finds AI adoption among OECD-country firms nearly tripled from ~7% to ~20% of businesses between 2021 and 2025, but workers with advanced AI capabilities remain just ~1% of the workforce. Larger firms and startups are pulling ahead; SMEs are held back by cost, infrastructure, and skills shortages, risking a widening two-tier labor market.', 'Organizational leaders should treat the 1%-advanced-skills figure as a capacity constraint on AI strategy, not just a training gap — it caps how fast any AI roadmap can actually be staffed.', ARRAY['skills development', 'macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-07-24-india-skills-report-2026-employability-climbs-women-surpass', '2026-07-24-1', '2026-07-24'::date, 1, 'India Skills Report 2026 — employability climbs, women surpass men', 'ETS/CII/AICTE/AIU/Taggd', 'https://organiser.org/2026/07/23/371280/bharat/how-india-is-building-a-future-ready-workforce-govts-skill-development-initiatives-explained/', 'India''s national employability score rose to 56.35% (from 54.81% in 2025, up from 46% in 2020), based on Global Employability Test results from over 100,000 candidates. For the first time in five years, women''s employability (54%) overtook men''s (51.5%), and hiring intent for FY26-27 rose to 40% from 29%.', 'A non-Western data point for capability builders: as WEF projects an 85-million global skilled-labor shortfall by 2030, India''s report frames itself as a surplus-talent exporter — worth watching for organizations building global delivery or offshore capability strategies.', ARRAY['skills development', 'macro signals']::text[], false, 'published'),
  ('2026-07-23-amazon-cuts-jobs-in-its-artificial-general-intelligence-unit', '2026-07-23-0', '2026-07-23'::date, 0, 'Amazon Cuts Jobs in Its Artificial General Intelligence Unit', 'CNBC', 'https://www.cnbc.com/2026/07/22/amazon-lays-off-some-employees-in-its-agi-unit.html', 'Amazon eliminated an undisclosed number of roles within its AGI organization on July 22, even as it plans roughly $200 billion in AI infrastructure spending this year. The company is reallocating talent toward customer-facing AI priorities rather than foundational AGI research, reflecting intensifying competitive pressure from OpenAI, Google, and Anthropic.', 'Signals that even well-resourced AI leaders are narrowing bets rather than broadly scaling AI headcount — a caution against assuming AI investment automatically expands AI-adjacent jobs.', ARRAY['workforce transformation', 'macro signals']::text[], false, 'published'),
  ('2026-07-23-apac-leads-in-ai-adoption-but-lags-in-workforce-readiness', '2026-07-23-1', '2026-07-23'::date, 1, 'APAC Leads in AI Adoption But Lags in Workforce Readiness', 'Aon', 'https://www.aon.com/apac/in-the-press/asia-newsroom/2026/apac-leads-in-ai-adoption-but-lags-in-workforce-readiness-aon-study-finds', 'Aon''s inaugural APAC Human Capital Trends Study finds 74% of APAC organizations have deployed or are piloting AI programs, moving from experimentation toward implementation faster than workforce and benefits structures can adapt — only 22% of employees in the region have access to customizable benefits versus a 33% global average.', 'Leaders scaling AI in Asia-Pacific markets should treat benefits and role-design modernization as a parallel workstream, not an afterthought to technology rollout.', ARRAY['macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-07-23-new-report-the-skills-gap-is-moving-faster-than-learning-can', '2026-07-23-2', '2026-07-23'::date, 2, 'New Report: The Skills Gap Is Moving Faster Than Learning Can Keep Up', 'Chief Learning Officer', 'https://www.chieflearningofficer.com/2026/06/17/the-skills-gap-is-moving-faster-than-we-are-new-report-finds/', 'A TalentLMS survey of 1,500 US respondents finds 70% of employees say they need faster ways to practice and apply new skills to keep pace with changing work demands, but 44% say day-to-day work leaves no time to learn; 53% are now pursuing skills development on their own initiative rather than through employer programs.', 'Points to a growing shift of learning responsibility onto individual workers — organizations that don''t build learning into workflow (rather than alongside it) risk falling further behind self-directed reskilling.', ARRAY['skills development']::text[], false, 'published'),
  ('2026-07-23-the-great-mismatch-shrinking-workforce-ai-and-labor', '2026-07-23-3', '2026-07-23'::date, 3, 'The "Great Mismatch": Shrinking Workforce, AI, and Labor Reallocation Through 2040', 'Indeed Hiring Lab', 'https://www.hiringlab.org/2026/05/14/how-a-shrinking-workforce-ai-and-labor-reallocation-will-define-the-next-15-years/', 'Analysis projects U.S. labor force participation will keep declining through 2034 as population aging outpaces new entrants, compounding with AI-driven task reallocation to reshape which occupations grow or shrink over the next 15 years — a structural rather than cyclical labor story.', 'Long-range workforce planning should treat demographic contraction and AI-driven reallocation as compounding forces, not separate risk categories, when sizing future talent pipelines.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-22-shrm-releases-skills-r-evolution-preparing-employees-for', '2026-07-22-0', '2026-07-22'::date, 0, 'SHRM releases "Skills (R)evolution: Preparing Employees for Tomorrow''s Jobs"', 'SHRM', 'https://www.shrm.org/about/press-room/shrm-research-finds-strategic-learning-and-development-drives-st', 'New SHRM research introduces a "Skills Strategist" model identifying practices that distinguish organizations best positioned for future-of-work readiness. A key gap: 72% of HR professionals say their L&D strategy is driven by skills needed in the next 1–2 years, while only 4% focus primarily on long-term skills needs.', 'Capability builders should treat the short-term/long-term L&D imbalance as a planning risk — organizations optimizing only for near-term skills gaps may be under-investing in durable adaptability.', ARRAY['skills development', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-22-upskillings-messy-middle-and-fixing-the-skills-mismatch', '2026-07-22-1', '2026-07-22'::date, 1, 'Upskilling''s "Messy Middle" and Fixing the Skills Mismatch', 'World Economic Forum', 'https://www.weforum.org/podcasts/meet-the-leader/episodes/jobs-skills-mismatch-future-maria-flynn/', 'WEF argues many labor markets face a skills mismatch, not a talent shortage — coordination failures between educators, employers, and workers are the bottleneck. 85% of employers plan retraining and 77% offer AI training, but 63% still cite skills gaps as their top barrier.', 'For organizational leaders, the fix isn''t more training volume but better coordination with education/credentialing ecosystems — a systems-thinking problem, not a budget problem.', ARRAY['skills development', 'macro signals']::text[], false, 'published'),
  ('2026-07-22-volkswagen-weighs-100-000-job-cuts-and-four-german-plant', '2026-07-22-2', '2026-07-22'::date, 2, 'Volkswagen weighs ~100,000 job cuts and four German plant closures', 'Euronews; CNBC', 'https://www.euronews.com/business/2026/07/09/volkswagen-faces-crunch-talks-over-100000-job-cuts-and-factory-closures', 'VW is negotiating cuts that would roughly double a 2024 union deal (50,000 → up to 100,000 positions), with production potentially ending at Hanover, Zwickau, Emden, and Audi Neckarsulm — about 15% of its workforce, driven by Chinese EV competition and margin pressure.', 'A concrete signal of how the green/EV transition is reshaping legacy manufacturing employment in the EU, with ripple effects for supplier regions and skills-transition programs.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-22-kpmg-australia-prepares-to-cut-up-to-1-000-jobs-and-reduce', '2026-07-22-3', '2026-07-22'::date, 3, 'KPMG Australia prepares to cut up to 1,000+ jobs and reduce partner pay up to 20%', 'Bloomberg; Reuters via AFR', 'https://www.bloomberg.com/news/articles/2026-07-14/kpmg-prepares-to-cut-staff-as-scandal-fallout-hits-afr-says', 'KPMG''s Australian consultancy arm is preparing cuts that could exceed 1,000 roles and reduce partner pay by up to a fifth, following a client-data misuse scandal that already forced out its chairman, CEO, and audit boss. The cuts await appointment of a permanent CEO, with CFO John Sams reported as the frontrunner.', 'Illustrates how governance failures, not technology, can trigger workforce contraction — a reminder that organizational readiness gaps (ethics and data governance) can trigger workforce shocks independent of AI or market cycles.', ARRAY['macro signals', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-22-2026-people-readiness-report-the-ai-adoption-readiness-gap', '2026-07-22-4', '2026-07-22'::date, 4, '2026 People Readiness Report: The AI Adoption-Readiness Gap Widens', 'Kyndryl', 'https://www.kyndryl.com/us/en/insights/people-readiness-report-2026', 'Kyndryl''s global survey of 1,100 senior business leaders across 8 countries finds only 23% believe their workforce is ready to use AI effectively, a 6-point drop from 2025, even as 77% report generative AI has scaled across multiple functions. A small "Pacesetters" cohort (9%) that paired role redesign, AI-specific change management, and workforce readiness was 1.5x more likely to report AI-driven revenue growth and twice as likely to report innovation gains.', 'Readiness is falling as adoption rises — a widening, not narrowing, gap that argues against "wait and see" capability-building approaches; the gap between deployment and readiness, not model capability, is now the central variable in AI ROI.', ARRAY['workforce transformation', 'research and insights', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-22-ai-job-postings-shift-from-disruption-signal-to-creation', '2026-07-22-5', '2026-07-22'::date, 5, 'AI Job Postings Shift From Disruption Signal to Creation Signal', 'Indeed Hiring Lab', 'https://www.hiringlab.org/2026/07/08/ai-and-job-postings-from-destruction-to-creation/', 'Analyzing postings since Claude Code''s February 2025 launch, Indeed found US software developer job postings up nearly 15% — read as early evidence that AI coding tools are expanding demand for certain technical roles rather than only displacing them. Just over 60% of postings with "AI" in the title now sit outside traditional tech companies.', 'The displacement-versus-augmentation debate has a live data point now: role creation in AI-adjacent technical work is outpacing the destruction narrative in this specific dataset, though the sample is narrow.', ARRAY['skills development', 'macro signals']::text[], false, 'published'),
  ('2026-07-17-ai-anxiety-is-driving-interest-toward-trades-welding', '2026-07-17-0', '2026-07-17'::date, 0, 'AI anxiety is driving interest toward trades — welding, plumbing, carpentry', 'Bloomberg', 'https://www.bloomberg.com/news/features/2026-07-17/ai-woes-drive-influencers-to-back-welding-plumbing-and-carpentry', 'Social media influencers and career advisors are steering followers toward manual trades as AI-driven anxiety about white-collar job security grows, coinciding with a genuine shortage of skilled tradespeople in manufacturing and construction. The piece frames this as a capability-migration response rather than a technology story.', 'An early-career recalibration signal — durable, non-automatable capability is being actively sought out, not just theorized about.', ARRAY['skills development']::text[], false, 'published'),
  ('2026-07-17-thomson-reuters-to-cut-up-to-500-engineering-jobs-as-ai', '2026-07-17-1', '2026-07-17'::date, 1, 'Thomson Reuters to cut up to 500 engineering jobs as AI adoption deepens', 'US News/AP', 'https://money.usnews.com/investing/news/articles/2026-07-13/thomson-reuters-to-cut-small-number-of-engineering-jobs', 'Thomson Reuters is cutting roughly 5.2% of its technology division while planning to add 250+ new engineering roles over two years, weighted toward senior and AI-native positions. The move reflects a broader talent recomposition rather than a straightforward headcount reduction.', 'A concrete case of skills-based reallocation — the same headcount pressure that shows up in aggregate WEF displacement figures, happening inside one named employer.', ARRAY['workforce transformation', 'skills development', 'research and insights']::text[], false, 'published'),
  ('2026-07-17-the-state-of-ai-fluency-2026', '2026-07-17-2', '2026-07-17'::date, 2, 'The State of AI Fluency 2026', 'AISA', 'https://aisa.to/state-of-ai-fluency', 'The first AI fluency benchmark built from behavioral assessment rather than self-report. Across 412 completed conversational assessments, the average score is 52/100, with only 12% reaching Advanced or Expert tier — and the self-selected sample likely overstates the true workforce average.', 'This is a concrete, measured version of the AI fluency vs. AI literacy distinction — most workers can talk about AI use but few demonstrate judgment-level fluency under assessment.', ARRAY['skills development', 'research and insights']::text[], false, 'published'),
  ('2026-07-17-why-britains-workforce-is-burning-out-new-data-reveals-the', '2026-07-17-3', '2026-07-17'::date, 3, 'Why Britain''s Workforce Is Burning Out: New Data Reveals the True Cost of the Workforce Transformation Gap', 'GlobeNewswire / HiBob', 'https://www.globenewswire.com/news-release/2026/07/09/3324563/0/en/Why-Britain-s-workforce-is-burning-out-New-data-reveals-the-true-cost-of-the-workforce-transformation-gap.html', '58% of UK workers report increased role pressure over the past two years; 42% are actively considering leaving due to workplace pressure, and 11% are already job-hunting.', 'This is the gap made measurable — capability demands rising faster than the organizational and human systems built to absorb them, showing up directly as attrition risk.', ARRAY['workforce transformation']::text[], false, 'published'),
  ('2026-07-17-mckinsey-and-company-the-critical-loss-of-on-the-job', '2026-07-17-4', '2026-07-17'::date, 4, 'McKinsey & Company: The Critical Loss of On-the-Job Mentoring Pipelines', 'McKinsey & Company', 'https://www.mckinsey.com/capabilities/people-and-organizational-performance/our-insights/building-expertise-in-the-age-of-ai-who-trains-the-next-generation', 'McKinsey''s new organizational analysis warns that as enterprises automate entry-level data processing and routine drafting, they are inadvertently dismantling their internal talent pipelines. Because junior professionals no longer execute the basic foundational work that historically built context and professional intuition, they are hitting an abrupt expertise cliff when moving into mid-level strategy positions. To resolve this, leaders must restructure work profiles to blend knowledge management, direct coaching loops, and simulation-based exercises directly into everyday workflows.', 'Capability builders must intentionally design structured practice environments and formal human-led feedback sessions to artificially recreate the implicit learning loops lost to software systems.', ARRAY['skills development', 'workforce transformation', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-15-future-of-remote-work-trends-every-professional-should-know', '2026-07-15-0', '2026-07-15'::date, 0, 'Future of Remote Work: Trends Every Professional Should Know', 'Internzity', 'https://www.linkedin.com/pulse/future-remote-work-trends-every-professional-should-know-internzity-ulvuf/', 'Remote work has moved from a temporary pandemic-era experiment to a permanent, cross-industry model, with hybrid arrangements emerging as the dominant preference for balancing flexibility and collaboration. AI now handles high-volume applicant screening and matching, but human judgment still decides final hires. Global, borderless hiring and a mainstream freelance economy are expanding access to opportunity, while employers increasingly weight demonstrated skills over credentials alone.', 'For professionals building careers in a skills-first, global labor market, continuous upskilling, a strong personal brand, and cross-cultural/remote-collaboration ability are becoming baseline requirements rather than differentiators.', ARRAY['workforce transformation', 'skills development']::text[], false, 'published'),
  ('2026-07-15-deloittes-2026-gen-z-and-millennial-survey-ai-adoption-is', '2026-07-15-1', '2026-07-15'::date, 1, 'Deloitte''s 2026 Gen Z and Millennial Survey: AI Adoption Is Outpacing Organizational Readiness', 'Deloitte Global', 'https://www.deloitte.com/content/dam/assets-shared/docs/campaigns/2026/2026-genz-millennial-survey.pdf', 'Deloitte''s 15th annual Gen Z and Millennial Survey (22,500+ respondents, 44 countries) finds AI use has gone mainstream — 74% of both Gen Zs and millennials now use AI at work, up sharply from 57%/56% a year ago — with many also using it for learning, career advice, and coping with work stress. But individual adoption is outpacing organizational readiness: roughly 30% say their employer isn''t prepared for AI-driven change, over a third don''t trust AI outputs, and Deloitte''s own 2026 State of AI in the Enterprise report found 84% of companies haven''t redesigned jobs around AI capabilities. Separately, the survey finds both generations deprioritizing traditional leadership tracks (only 6% cite it as their top career goal, citing burnout/work-life balance) in favor of continuous skill-building — AI fluency, leadership, and creativity top the list of skills they want to develop next.', 'The gap between employee AI adoption and organizational readiness — training, trust, and role redesign — is the practical bottleneck leaders should address now; treating AI as a work-redesign and change-management effort (not a tool rollout) is what separates organizations capturing value from those with fragmented experimentation.', ARRAY['workforce transformation', 'skills development', 'research and insights']::text[], false, 'published'),
  ('2026-07-10-the-emergence-of-the-ai-work-architect-and-ai-steward', '2026-07-10-0', '2026-07-10'::date, 0, 'The Emergence of the "AI Work Architect" and "AI Steward"', 'World Economic Forum', 'https://www.weforum.org/stories/2026/06/future-of-work-define-roles-humans-ai/', 'As autonomous agentic systems absorb the corporate execution layer — data synthesis, drafting, optimization — the WEF outlines a structural shift toward high-leverage human responsibility. The research introduces two critical human roles required to maintain operational guardrails: the AI Work Architect, who designs real-world constraints, assumptions, and objectives for technical processing, and the AI Steward, who audits automated outputs for context, safety, and human risk. The analysis stresses that corporate learning must look past simple interface training to blend domain expertise with rigorous decision rights and risk evaluation.', 'Knowledge workers must actively transition their career identities from execution specialists to systems overseers, mastering the workflow loops before and after an automated system operates.', ARRAY['skills development', 'workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-10-mckinsey-hr-monitor-2026-a-feedback-vacuum-and-a-risk-averse', '2026-07-10-1', '2026-07-10'::date, 1, 'McKinsey HR Monitor 2026: A Feedback Vacuum and a Risk-Averse Talent Freeze', 'McKinsey & Company', 'https://www.mckinsey.com/~/media/mckinsey/business%20functions/people%20and%20organizational%20performance/our-insights/hr%20monitor%202026%20a%20turning%20point%20for%20the%20people%20function/hr-monitor-2026-a-turning-point-for-the-people-function_final.pdf', 'McKinsey''s global HR Monitor 2026 survey of 1,300 HR professionals and 5,500 employees surfaces two connected structural gaps. On feedback and development: HR believes only 3% of employees miss performance evaluations, but 20% of workers report receiving no career development or feedback meetings at all — and HR overestimates training time by nearly double, masking that 24% of the global knowledge workforce did zero training in the past year. On mobility: the same tracking shows voluntary attrition down 2 points year-over-year, with workers ranking compensation (52%), work-life balance (46%), and job security (45%) above career exploration when deciding to stay.', 'Corporate capability builders must move past policy tracking to ground-level audits of where feedback and training loops are actually breaking down — and shouldn''t read flat turnover as healthy retention rather than risk-averse stagnation; internal mobility, transparency, and fair workload distribution matter more than external recruitment liquidity right now.', ARRAY['workforce transformation', 'leadership and culture', 'macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-07-10-study-finds-ceos-pushing-return-to-office-mandates-share-one', '2026-07-10-2', '2026-07-10'::date, 2, 'Study Finds CEOs Pushing Return-to-Office Mandates Share One Trait: Narcissism', 'Fortune', 'https://fortune.com/2026/06/25/return-to-office-ceos-ego-research/', 'A six-year study by Wharton''s Adam Grant with Marissa Shandell and Courtney Elliott, using proxies like CEO pay-package size and photo size in annual reports, found narcissism predicts RTO enthusiasm — in-person settings let leaders "direct and inspire" (and be admired) in ways video calls don''t. An experimental prime (reflecting on Steve Jobs'' and Larry Ellison''s egos) causally increased opposition to remote work among the same leaders.', 'This reframes RTO mandates as a leadership-psychology issue rather than a pure productivity argument, which matters for anyone advising on change management around hybrid policy — the stated rationale and the actual driver may not be the same thing.', ARRAY['leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-10-ai-literacy-named-the-top-human-skill-as-uk-employers-de', '2026-07-10-3', '2026-07-10'::date, 3, 'AI Literacy Named the Top Human Skill as UK Employers De-Prioritize Credentials', 'MyPerfectCV (via Allwork.Space)', 'https://allwork.space/2026/07/ai-literacy-is-now-an-essential-human-skill-as-tech-rapidly-reshapes-the-u-k-workforce', 'A vendor-commissioned UK study found 68% of employers rate enthusiasm as the top success predictor versus 8% for university degree, with AI literacy — defined as prompting effectively and critically evaluating output — now the number one in-demand skill. Separately, FutureDotNow data cited in the piece shows 54% of UK workers lack baseline digital competencies, a substantial barrier to AI adoption. Note: this is a vendor-commissioned study promoted as a press release — the topline framing is marketing-adjacent, and the underlying stats are directionally useful rather than rigorously validated.', 'The credential-to-capability shift is showing up as clearly in the UK as in the US; leaders should read AI literacy as one entry in a broader human-skills stack (alongside adaptability, judgment, communication), not a standalone technical requirement.', ARRAY['skills development', 'macro signals']::text[], false, 'published'),
  ('2026-07-10-chief-people-officers-outlook-what-geopolitics-and-the-ai', '2026-07-10-4', '2026-07-10'::date, 4, 'Chief People Officers'' Outlook: What Geopolitics and the AI "Scaling Stage" Mean for Your Day-to-Day', 'World Economic Forum', 'https://reports.weforum.org/docs/WEF_Chief_People_Officers_Outlook_May_2026.pdf', 'The WEF''s May 2026 Chief People Officers'' Outlook — a survey of 140+ HR leaders at large global employers, fielded January–March 2026 — shows the ground shifting under knowledge workers in two ways. First, 83% of CPOs now expect their companies to move into the "scaling" stage of AI deployment within 6–12 months, meaning AI tools stop being optional pilots and start getting embedded into how your actual workflows and role expectations are defined — a marked jump from the exploratory phase most organizations were still in a year ago. Second, employers say the real bottleneck isn''t headcount, it''s matching — companies report they can''t find people with the specific, current skills they need, even where job openings exist, and are prioritizing organizational redesign (74%) and upskilling (70%) to close that gap.', 'If your employer is entering the "scaling" phase, expect your role and workflows to get actively redesigned around AI tools in the next year, not just handed new software — the workers who benefit are the ones who treat this as a chance to move into higher-judgment, oversight-style work rather than waiting to be told what changed. And since companies are explicitly rewarding skills-matching over tenure or headcount, the practical move is to make your current, specific skills visible and current (not just "AI-aware" in general) — internal mobility and upskilling programs are where employers say they''re putting resources, so that''s where to lean in first.', ARRAY['workforce transformation', 'skills development', 'macro signals']::text[], false, 'published'),
  ('2026-07-09-how-investing-in-people-can-support-future-economic-growth', '2026-07-09-0', '2026-07-09'::date, 0, 'How Investing in People Can Support Future Economic Growth', 'World Economic Forum', 'https://www.weforum.org/stories/2026/06/china-building-assets-investing-in-people/', 'China''s 15th Five-Year Plan (2026–2030) sets out a dual growth strategy investing in both physical assets and people, marking a shift from the country''s traditional infrastructure-led model. WEF argues that stronger human capital — higher skills, better health, greater adaptability — boosts productivity, absorbs new technology, and builds labor-market resilience, citing the US, Germany, Singapore, and South Korea as economies that escaped the middle-income trap by building education hubs before technology hubs.', 'As China''s low-labor-cost growth model fades, local talent quality, skills matching, and joint talent development with educational institutions are becoming standard requirements for companies operating there — a preview of how human capital investment is becoming a direct input to competitiveness, not a soft cost.', ARRAY['workforce transformation', 'macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-07-09-from-jobs-to-skills-to-outcomes-rethinking-how-work-gets', '2026-07-09-1', '2026-07-09'::date, 1, 'From Jobs to Skills to Outcomes: Rethinking How Work Gets Done', 'Deloitte Insights', 'https://www.deloitte.com/us/en/insights/topics/talent/future-of-workforce-planning/planning-work-outcomes.html', 'Deloitte finds organizations shifting workforce planning away from rigid job structures toward task- and skills-based approaches for greater flexibility — but argues the next frontier is outcome-driven planning, where roles are defined by problems solved rather than tasks performed, giving workers autonomy within clear guardrails. 93% of surveyed leaders say moving away from the job construct matters for organizational success, yet only 22% of organizations can effectively break jobs into component tasks today, and 71% of workers already perform duties outside their job descriptions.', 'Organizations using outcome-based roles are nearly twice as likely to retain high performers and place talent effectively — a signal that leaders shouldn''t chase one universal model, but start with mission-critical skills and stay flexible about whether task-based or outcome-based planning fits a given part of the business.', ARRAY['workforce transformation', 'skills development', 'research and insights']::text[], false, 'published'),
  ('2026-07-09-ai-and-the-future-of-entry-level-work-a-framework-for', '2026-07-09-2', '2026-07-09'::date, 2, 'AI and the Future of Entry-Level Work: A Framework for Safeguarding Early-Career Pathways', 'World Economic Forum (with PwC)', 'https://reports.weforum.org/docs/WEF_Artificial_Intelligence_and_the_Future_of_Entry_Level_Work_2026.pdf', 'WEF and PwC find more than one in three young workers globally (37%) are in occupations with medium-to-high exposure to AI-driven task change, rising to three in four in some regions — with entry-level hiring already slowing in higher-exposure roles, though broader economic factors are contributing too. The report proposes a four-part framework — job access, job design, talent pipelines, and education-system alignment — for redesigning entry-level roles rather than eliminating them, noting a parallel shift where 42% of Gen Z workers (including 37% of bachelor''s degree holders) are now in or pursuing blue-collar and skilled trades.', 'The prescription is redesign, not preservation as-is: leaders should treat entry-level roles as a pipeline to actively re-engineer for AI-era work rather than either freezing hiring or restructuring around it passively.', ARRAY['workforce transformation', 'skills development', 'research and insights']::text[], false, 'published'),
  ('2026-07-08-microsoft-cuts-4-800-jobs-frames-it-as-business', '2026-07-08-0', '2026-07-08'::date, 0, 'Microsoft cuts 4,800 jobs, frames it as business transformation, not AI replacement', 'Official Microsoft Blog', 'https://blogs.microsoft.com/blog/2026/07/06/the-latest-in-our-company-transformation/', 'Chief People Officer Amy Coleman announced the elimination of roughly 4,800 roles (2.1% of global headcount), hitting Xbox and commercial sales hardest. Coleman explicitly stated the cuts are not AI replacing workers, but framed them as part of an ongoing reorganization driven by how technology, customer expectations, and business models are shifting, with "more changes ahead."', 'A test case for how much "this isn''t about AI" messaging holds up under scrutiny — leaders watching this space should note the gap between the stated rationale and the AI-infrastructure spending driving it.', ARRAY['workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-08-oecd-skills-first-hiring-is-becoming-structural-not', '2026-07-08-1', '2026-07-08'::date, 1, 'OECD: skills-first hiring is becoming structural, not experimental', 'OECD', 'https://www.oecd.org/en/publications/a-skills-first-labour-market_2e1b85f0-en.html', 'The OECD''s follow-up report argues skills-first approaches to hiring, talent management, and development are moving from pilot to necessity for labor market functioning and productivity, while flagging persistent barriers: uneven digital access, weak skills-validation infrastructure, and employer distrust of non-traditional credentials.', 'The barriers named here are the same ones that stall most skills-based transformation efforts internally — credentialing trust and validation infrastructure, not employee willingness, are the binding constraint.', ARRAY['skills development', 'research and insights', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-08-green-and-ai-skills-are-converging-into-a-twin-transition', '2026-07-08-2', '2026-07-08'::date, 2, 'Green and AI skills are converging into a "twin transition," and supply isn''t keeping up', 'LinkedIn Economic Graph', 'https://economicgraph.linkedin.com/workforce-data', 'LinkedIn''s Economic Graph data shows AI talent rapidly adding green skills (operational efficiency use up 579%, lifecycle management up 152%), while overall climate-skill growth has slowed from 5.5% (2023–24) to 4.3% (2024–25). Only about a third of Europe''s AI workforce holds meaningful green expertise, even as green hiring grows twice as fast as green-skills acquisition.', 'A concrete example of two "future skills" narratives (AI fluency, sustainability) colliding in the same labor pool faster than training pipelines can respond — worth watching as a leading indicator for other skill convergences.', ARRAY['skills development', 'macro signals']::text[], false, 'published'),
  ('2026-07-07-pwcs-2026-global-ai-jobs-barometer-finds-a-two-track-labor', '2026-07-07-0', '2026-07-07'::date, 0, 'PwC''s 2026 Global AI Jobs Barometer finds a "two-track" labor market emerging', 'PwC', 'https://www.pwc.com/gx/en/news-room/press-releases/2026/pwc-2026-ai-jobs-barometer.html', 'PwC''s analysis of job postings and wage data finds AI is splitting roles into "professionalised" (AI automates routine tasks, human judgment gets emphasized) and "democratised" (AI lowers the skill floor) tracks. Professionalised roles are growing twice as fast with 42% faster wage growth; the AI skills wage premium hit 62%, up from 57% a year earlier.', 'Gives leaders and practitioners a data-backed way to argue that augmentation-track roles — not automation-track ones — are where career and compensation upside concentrates right now.', ARRAY['skills development', 'macro signals', 'research and insights']::text[], false, 'published'),
  ('2026-07-07-mckinseys-state-of-organizations-2026-5-on-people-for-every', '2026-07-07-1', '2026-07-07'::date, 1, 'McKinsey''s State of Organizations 2026: "$5 on people for every $1 on tech" as the AI value threshold', 'McKinsey & Company', 'https://www.mckinsey.com/capabilities/people-and-organizational-performance/our-insights/the-state-of-organizations', 'Drawing on a survey of 10,000+ senior executives across 15 countries, McKinsey identifies three converging forces reshaping organizations — AI/tech acceleration, economic and geopolitical disruption, and shifting employee expectations — and reports one executive''s estimate that realizing AI value requires spending roughly $5 on people for every $1 spent on technology.', 'The $5-to-1 ratio is a concrete, quotable frame for practitioners trying to get leadership buy-in for capability-building budgets alongside tech spend.', ARRAY['workforce transformation', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-07-06-employers-who-laid-off-workers-citing-ai-are-already', '2026-07-06-0', '2026-07-06'::date, 0, 'Employers who laid off workers citing AI are already starting to regret it', 'CNBC', 'https://www.cnbc.com/2026/07/01/employers-who-laid-off-workers-for-ai-are-reversing-their-decisions.html', 'Ford, Commonwealth Bank of Australia, and IBM are all reversing AI-driven layoffs after automation couldn''t cover the full scope of the work: Ford rehired engineers for quality issues, CBA restored customer service staff after AI voice bots couldn''t handle call volume, and IBM is tripling entry-level hiring after its AI handled only 94% of HR requests, missing the ethically complex 6%.', 'Concrete evidence that cutting headcount before building the human oversight layer is proving costly and reversible.', ARRAY['workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-06-challenger-report-june-layoffs-cool-to-45-849-down-53-from', '2026-07-06-1', '2026-07-06'::date, 1, 'Challenger Report: June layoffs cool to 45,849, down 53% from May; AI leads reasons for fourth consecutive month', 'Challenger, Gray & Christmas, Inc.', 'https://www.challengergray.com/blog/challenger-report-june-layoffs-cool-to-45849-down-53-from-may-ai-leads-reasons-for-fourth-consecutive-month/', 'Total job cuts fell sharply month over month, but AI remained the top-cited reason for cuts (31% of June''s total) for a fourth straight month; tech now accounts for nearly a third of all 2026 layoffs.', 'AI-attributed restructuring looks like a steady-state feature of 2026 workforce planning, not a one-time shock.', ARRAY['macro signals', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-06-the-human-skills-employers-are-hiring-for-that-cant-be', '2026-07-06-2', '2026-07-06'::date, 2, 'The Human Skills Employers Are Hiring For That Can''t Be Replaced By AI', 'Forbes', 'https://www.forbes.com/sites/courtney-connley-hampton/2026/07/02/ai-is-changing-work-these-are-the-human-skills-employers-are-hiring-for/', 'Drawing on the 2026 Corporate Recruiters Survey (600+ recruiters, 39 countries), communication and problem-solving top employer priorities, with hiring increasingly weighted toward learning mindset and leadership capability over narrow technical depth.', 'Durable human capabilities are becoming the differentiator, not a hedge against AI.', ARRAY['skills development', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-05-gartner-20-of-finance-organizations-will-pivot-all-talent', '2026-07-05-0', '2026-07-05'::date, 0, 'Gartner: 20% of Finance Organizations Will Pivot All Talent Investment to Digital Capabilities by 2028', 'Gartner', 'https://www.gartner.com/en/newsroom/press-releases/2026-07-01-gartner-predicts-20-percent-of-finance-orgs-will-pivot', 'Gartner projects that by 2028, a fifth of finance organizations will stop hiring or developing talent that lacks digital fluency, redirecting all talent investment toward advanced digital capabilities. Current finance teams are 50% basic tech users, 35% digitally literate, and only 15% "digital talent" — a mix Gartner says is misaligned with AI-driven finance functions.', 'A concrete data point on how fast the skills bar is rising inside a single function, useful as a proxy for what''s likely happening across other back-office functions facing similar AI-driven redesign.', ARRAY['skills development', 'workforce transformation', 'macro signals']::text[], false, 'published'),
  ('2026-07-05-wef-the-five-faces-of-human-readiness-for-ai-adoption', '2026-07-05-1', '2026-07-05'::date, 1, 'WEF: The Five Faces of Human Readiness for AI Adoption', 'World Economic Forum', 'https://www.weforum.org/stories/2026/06/ai-workplace-adoption-readiness/', 'Research identifies a split between a top-down narrative from tech leaders focused on breakthroughs, and a bottom-up narrative from employees shaped by job-loss fears, concerns about eroding critical thinking, and distrust of leadership framing. The piece segments workforce reactions into five distinct readiness profiles rather than treating adoption as binary.', 'Reinforces that "readiness" isn''t a single organizational dial — leaders managing AI rollouts are managing five different conversations at once, not one.', ARRAY['workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-07-05-deloitte-winning-organizations-will-build-the-human', '2026-07-05-2', '2026-07-05'::date, 2, 'Deloitte: Winning Organizations Will Build the "Human Advantage"', 'Deloitte', 'https://www.prnewswire.com/news-releases/deloitte-in-a-new-era-of-work-winning-organizations-will-build-the-human-advantage-302703266.html', '7 in 10 business leaders say speed and agility are now their primary competitive strategy, with orchestrating people and resources cited as the top driver. Only 6% of leaders say they''re making real progress designing effective human-AI interaction, despite it being flagged as the key differentiator.', 'The 6% figure is the sharpest evidence yet of the pilot-to-production gap showing up not in technology metrics but in workforce design — most organizations haven''t done the human-side work regardless of tool maturity.', ARRAY['leadership and culture', 'workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-07-03-middle-managers-are-absorbing-the-cost-of-ai-adoption', '2026-07-03-0', '2026-07-03'::date, 0, 'Middle managers are absorbing the cost of AI adoption', 'Harvard Business Review', 'https://hbr.org/2026/06/ai-adoption-is-overloading-your-middle-managers', 'Harvard Business School research (18 interviews across two consulting firms) found senior leaders capturing AI''s strategic upside while middle managers absorb new work — validating AI outputs, catching errors, coaching teams — without added support or relief from existing delivery pressure.', 'Middle-management capacity, not model capability, is emerging as the real adoption bottleneck.', ARRAY['leadership and culture', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-02-canaries-in-the-coal-mine-six-facts-about-the-recent', '2026-07-02-0', '2026-07-02'::date, 0, 'Canaries in the Coal Mine? Six Facts About the Recent Employment Effects of AI', 'Stanford Digital Economy Lab', 'https://digitaleconomy.stanford.edu/publication/canaries-in-the-coal-mine-six-facts-about-the-recent-employment-effects-of-artificial-intelligence/', 'Using ADP payroll data across tens of thousands of firms, researchers find a 16% relative decline in employment for 22–25 year-olds in AI-exposed occupations (software developers down nearly 20%), while more experienced workers in the same roles are largely unaffected. The effect is concentrated specifically in roles where AI automates rather than augments tasks — adjustment is happening through hiring, not compensation.', 'Early-career hiring pipelines in automation-exposed roles are the leading indicator to watch, not aggregate headcount.', ARRAY['macro signals', 'workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-07-02-88-of-leaders-are-confident-their-reorganization-will', '2026-07-02-1', '2026-07-02'::date, 1, '88% of Leaders Are Confident Their Reorganization Will Deliver, Only 36% of Employees Agree', 'Bain & Company', 'https://www.bain.com/about/media-center/press-releases/2026/88-of-leaders-are-confident-their-reorganization-will-deliver--only-36-of-employees-agree-bain--co-research/', 'Survey of nearly 1,000 global executives and employees post-reorganization finds a sharp leadership-employee perception gap: only 22% of employees felt they got sufficient training or tools to adapt, and only 57% of middle managers agreed leadership had adequately supported the transition, versus 80%+ of leaders who believed they had.', 'Structural redesign without matched investment in transition support is a recurring, measurable failure mode — worth citing whenever "restructuring" is proposed as a fix.', ARRAY['leadership and culture', 'workforce transformation']::text[], false, 'published'),
  ('2026-07-02-top-future-of-work-trends-for-chros-in-2026', '2026-07-02-2', '2026-07-02'::date, 2, 'Top Future of Work Trends for CHROs in 2026', 'Gartner', 'https://www.gartner.com/en/newsroom/press-releases/2026-01-12-gartner-identifies-the-top-future-of-work-trends-for-chros-in-2026', 'Gartner''s 2026 CHRO framework names "workslop" — fast, low-quality AI-assisted output from employees pressured to use AI everywhere — as a defining risk, alongside warnings that only 1 in 50 AI initiatives is delivering transformative value despite bold CEO growth targets tied to AI. As technology platforms become commoditized, Gartner also finds enterprise value shifting to "process experts" over "technical prodigies": top firms are reweighting recruitment toward systems thinking and end-to-end workflow re-engineering, while reintroducing high-touch practices like live skill assessments and AI-free behavioral checkouts to counter AI-padded application fraud.', '"Workslop" gives leaders a concrete term for a cost that''s easy to overlook when adoption metrics look strong but output quality doesn''t — and the hiring bar it points to is shifting away from basic tool literacy toward the contextual judgment and systems thinking needed to re-engineer whole workflows.', ARRAY['skills development', 'workforce transformation', 'leadership and culture']::text[], false, 'published')
